package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Create-time household guard for {@code POST /owners}: rejects a request whose last name and
 * address both match an existing owner's, with a 409 via {@link DuplicateHouseholdException}.
 *
 * <p>Last name is compared case-insensitively with collapsed whitespace and address in its
 * normalised form (see {@link OwnerAddress#normalize}), so values that differ only in letter
 * case, spacing or abbreviation count as the same household. A request may opt out
 * of the check by setting {@code sharesHousehold} true (several owners legitimately share one
 * household), in which case the duplicate is allowed.
 */
public class CheckOwnerHouseholdUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (OwnerHousehold.matches(request, existing)) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * Create-time uniqueness guard for {@code POST /owners}: rejects a request whose telephone is
 * already used by an existing owner, with a 409 via {@link DuplicateTelephoneException}.
 *
 * <p>Runs after {@link NormalizeOwnerTelephone} so the request telephone is the stored E.164
 * form, and compares against each existing owner's telephone canonicalised the same way
 * ({@link OwnerTelephone#toE164(String)}) so the check is independent of how existing values
 * happen to be formatted. Runs before {@link BuildOwner}.
 */
public class CheckOwnerTelephoneUnique {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateTelephoneException {
        String telephone = request.getTelephone();
        for (Owner existing : ownerRepository.findAll()) {
            if (telephone.equals(OwnerTelephone.toE164(existing.getTelephone()))) {
                throw new DuplicateTelephoneException(telephone);
            }
        }
    }
}

